class Solution:
    def mostExpensiveItem(self, primeOne: int, primeTwo: int) -> int:
        a, b = primeOne, primeTwo
        limit = a * b
        dp = [False] * (limit + 1)
        dp[0] = True
        ans = 0
        for x in range(1, limit + 1):
            dp[x] = (x >= a and dp[x - a]) or (x >= b and dp[x - b])
            if not dp[x]:
                ans = x
        return ans

