class Solution {
public:
    int mostExpensiveItem(int primeOne, int primeTwo) {
        int a = primeOne, b = primeTwo, limit = a * b;
        vector<char> dp(limit + 1, 0);
        dp[0] = 1;
        int ans = 0;
        for (int x = 1; x <= limit; ++x) {
            dp[x] = (x >= a && dp[x - a]) || (x >= b && dp[x - b]);
            if (!dp[x]) ans = x;
        }
        return ans;
    }
};

